-- ============================================================
-- PORTFOLIO ANALYSIS - COMPLETE SQL SCRIPT
-- Generated: 2026-06-25
-- Case study: five asset portfolio, USD 95M notional
-- Assets: IXN (17.5%), QQQ (22.1%), IEF (28.5%), VNQ (8.9%), GLD (23.0%)
-- Data: 4,340 daily price records (868 per ticker, 2023-01-03 to 2026-06-18)
-- ============================================================

-- ============================================================
-- STEP 1: SCHEMA CREATION
-- ============================================================
DROP SCHEMA IF EXISTS portfolio_analysis;
CREATE SCHEMA portfolio_analysis;
USE portfolio_analysis;

-- ============================================================
-- STEP 2: TABLE CREATION
-- ============================================================
DROP TABLE IF EXISTS stock_prices;
CREATE TABLE stock_prices (
    id            INT AUTO_INCREMENT PRIMARY KEY,
    ticker        VARCHAR(10)    NOT NULL,
    price_date    DATE           NOT NULL,
    open_price    DECIMAL(12,4)  NOT NULL,
    high_price    DECIMAL(12,4)  NOT NULL,
    low_price     DECIMAL(12,4)  NOT NULL,
    close_price   DECIMAL(12,4)  NOT NULL,
    adj_close     DECIMAL(12,4)  NOT NULL,
    volume        BIGINT         NOT NULL,
    UNIQUE INDEX idx_ticker_date (ticker, price_date),
    INDEX idx_date (price_date),
    INDEX idx_ticker (ticker)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- ============================================================
-- STEP 3: DATA INSERTS (4,340 rows)
-- ============================================================

-- ============================================================
-- STEP 4: DATA VERIFICATION
-- ============================================================

SELECT ticker,
       COUNT(*)        AS row_count,
       MIN(price_date) AS first_date,
       MAX(price_date) AS last_date
FROM stock_prices
GROUP BY ticker
ORDER BY ticker;

SELECT COUNT(*) AS total_rows FROM stock_prices;

-- ============================================================
-- QUESTION 1 (20 pts):
-- What is the most recent 12M, 18M, 24M return for each
-- security and for the entire portfolio?
--
-- Method: (end_price - start_price) / start_price * 100
-- Uses the most recent trading date as the endpoint.
-- Portfolio return = weighted sum of individual returns.
-- ============================================================

WITH end_p AS (
  SELECT ticker, adj_close
  FROM stock_prices
  WHERE price_date = (SELECT MAX(price_date) FROM stock_prices)
),
start_12 AS (
  SELECT sp.ticker, sp.adj_close
  FROM stock_prices sp
  INNER JOIN (
    SELECT ticker, MIN(price_date) AS d
    FROM stock_prices
    WHERE price_date >= DATE_SUB((SELECT MAX(price_date) FROM stock_prices), INTERVAL 12 MONTH)
    GROUP BY ticker
  ) t ON sp.ticker = t.ticker AND sp.price_date = t.d
),
start_18 AS (
  SELECT sp.ticker, sp.adj_close
  FROM stock_prices sp
  INNER JOIN (
    SELECT ticker, MIN(price_date) AS d
    FROM stock_prices
    WHERE price_date >= DATE_SUB((SELECT MAX(price_date) FROM stock_prices), INTERVAL 18 MONTH)
    GROUP BY ticker
  ) t ON sp.ticker = t.ticker AND sp.price_date = t.d
),
start_24 AS (
  SELECT sp.ticker, sp.adj_close
  FROM stock_prices sp
  INNER JOIN (
    SELECT ticker, MIN(price_date) AS d
    FROM stock_prices
    WHERE price_date >= DATE_SUB((SELECT MAX(price_date) FROM stock_prices), INTERVAL 24 MONTH)
    GROUP BY ticker
  ) t ON sp.ticker = t.ticker AND sp.price_date = t.d
)
SELECT
  e.ticker,
  ROUND((e.adj_close - s12.adj_close) / s12.adj_close * 100, 2) AS return_12m_pct,
  ROUND((e.adj_close - s18.adj_close) / s18.adj_close * 100, 2) AS return_18m_pct,
  ROUND((e.adj_close - s24.adj_close) / s24.adj_close * 100, 2) AS return_24m_pct
FROM end_p e
JOIN start_12 s12 ON e.ticker = s12.ticker
JOIN start_18 s18 ON e.ticker = s18.ticker
JOIN start_24 s24 ON e.ticker = s24.ticker

UNION ALL

SELECT
  'PORTFOLIO' AS ticker,
  ROUND(SUM((e.adj_close - s12.adj_close) / s12.adj_close * 100 *
    CASE e.ticker WHEN 'IXN' THEN 0.175 WHEN 'QQQ' THEN 0.221 WHEN 'IEF' THEN 0.285
                  WHEN 'VNQ' THEN 0.089 WHEN 'GLD' THEN 0.230 END), 2) AS return_12m_pct,
  ROUND(SUM((e.adj_close - s18.adj_close) / s18.adj_close * 100 *
    CASE e.ticker WHEN 'IXN' THEN 0.175 WHEN 'QQQ' THEN 0.221 WHEN 'IEF' THEN 0.285
                  WHEN 'VNQ' THEN 0.089 WHEN 'GLD' THEN 0.230 END), 2) AS return_18m_pct,
  ROUND(SUM((e.adj_close - s24.adj_close) / s24.adj_close * 100 *
    CASE e.ticker WHEN 'IXN' THEN 0.175 WHEN 'QQQ' THEN 0.221 WHEN 'IEF' THEN 0.285
                  WHEN 'VNQ' THEN 0.089 WHEN 'GLD' THEN 0.230 END), 2) AS return_24m_pct
FROM end_p e
JOIN start_12 s12 ON e.ticker = s12.ticker
JOIN start_18 s18 ON e.ticker = s18.ticker
JOIN start_24 s24 ON e.ticker = s24.ticker;

-- ============================================================
-- QUESTION 2 (20 pts):
-- What are the correlations between your assets?
--
-- Part A: Pairwise Pearson correlations (all 10 pairs)
--   Formula: (AVG(x*y) - AVG(x)*AVG(y)) / (STD(x)*STD(y))
--
-- Part B: Variance fallback (if corr() is unavailable)
--   Shows variance and std dev per ticker for comparison.
-- ============================================================

-- Part A: Pairwise correlations

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
),
daily AS (
  SELECT price_date,
         MAX(CASE WHEN ticker='IXN' THEN ror END) AS ixn_ror,
         MAX(CASE WHEN ticker='QQQ' THEN ror END) AS qqq_ror,
         MAX(CASE WHEN ticker='IEF' THEN ror END) AS ief_ror,
         MAX(CASE WHEN ticker='VNQ' THEN ror END) AS vnq_ror,
         MAX(CASE WHEN ticker='GLD' THEN ror END) AS gld_ror
  FROM r
  WHERE ror IS NOT NULL
  GROUP BY price_date
  HAVING MAX(CASE WHEN ticker='IXN' THEN ror END) IS NOT NULL
)
SELECT 'IXN-QQQ' AS pair, ROUND((AVG(ixn_ror*qqq_ror) - AVG(ixn_ror)*AVG(qqq_ror)) / (STD(ixn_ror)*STD(qqq_ror)), 3) AS correlation FROM daily
UNION ALL
SELECT 'IXN-IEF', ROUND((AVG(ixn_ror*ief_ror) - AVG(ixn_ror)*AVG(ief_ror)) / (STD(ixn_ror)*STD(ief_ror)), 3) FROM daily
UNION ALL
SELECT 'IXN-VNQ', ROUND((AVG(ixn_ror*vnq_ror) - AVG(ixn_ror)*AVG(vnq_ror)) / (STD(ixn_ror)*STD(vnq_ror)), 3) FROM daily
UNION ALL
SELECT 'IXN-GLD', ROUND((AVG(ixn_ror*gld_ror) - AVG(ixn_ror)*AVG(gld_ror)) / (STD(ixn_ror)*STD(gld_ror)), 3) FROM daily
UNION ALL
SELECT 'QQQ-IEF', ROUND((AVG(qqq_ror*ief_ror) - AVG(qqq_ror)*AVG(ief_ror)) / (STD(qqq_ror)*STD(ief_ror)), 3) FROM daily
UNION ALL
SELECT 'QQQ-VNQ', ROUND((AVG(qqq_ror*vnq_ror) - AVG(qqq_ror)*AVG(vnq_ror)) / (STD(qqq_ror)*STD(vnq_ror)), 3) FROM daily
UNION ALL
SELECT 'QQQ-GLD', ROUND((AVG(qqq_ror*gld_ror) - AVG(qqq_ror)*AVG(gld_ror)) / (STD(qqq_ror)*STD(gld_ror)), 3) FROM daily
UNION ALL
SELECT 'IEF-VNQ', ROUND((AVG(ief_ror*vnq_ror) - AVG(ief_ror)*AVG(vnq_ror)) / (STD(ief_ror)*STD(vnq_ror)), 3) FROM daily
UNION ALL
SELECT 'IEF-GLD', ROUND((AVG(ief_ror*gld_ror) - AVG(ief_ror)*AVG(gld_ror)) / (STD(ief_ror)*STD(gld_ror)), 3) FROM daily
UNION ALL
SELECT 'VNQ-GLD', ROUND((AVG(vnq_ror*gld_ror) - AVG(vnq_ror)*AVG(gld_ror)) / (STD(vnq_ror)*STD(gld_ror)), 3) FROM daily
ORDER BY pair;

-- Part B: Variance fallback (per-ticker variance and sigma)

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
)
SELECT ticker,
       COUNT(*)                                   AS n_obs,
       ROUND(AVG(ror)*252*100, 4)                 AS ann_mean_return_pct,
       ROUND(VARIANCE(ror), 8)                    AS daily_variance,
       ROUND(STD(ror), 6)                         AS daily_std_dev,
       ROUND(STD(ror)*SQRT(252)*100, 2)           AS ann_sigma_pct
FROM r
WHERE ror IS NOT NULL
GROUP BY ticker
ORDER BY ticker;

-- ============================================================
-- QUESTION 3 (20 pts):
-- What is the most recent 12M sigma (risk) for each security
-- and for the entire portfolio?
--
-- Sigma = STD(daily_return) * SQRT(252) * 100
-- Filtered to the most recent 12 months of trading data.
-- Portfolio sigma uses the weighted daily portfolio return,
-- which captures the diversification effect.
-- ============================================================

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
),
daily AS (
  SELECT price_date,
         MAX(CASE WHEN ticker='IXN' THEN ror END) AS ixn_ror,
         MAX(CASE WHEN ticker='QQQ' THEN ror END) AS qqq_ror,
         MAX(CASE WHEN ticker='IEF' THEN ror END) AS ief_ror,
         MAX(CASE WHEN ticker='VNQ' THEN ror END) AS vnq_ror,
         MAX(CASE WHEN ticker='GLD' THEN ror END) AS gld_ror,
         0.175*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.221*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.285*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.089*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS port_ror
  FROM r
  WHERE ror IS NOT NULL
    AND price_date >= DATE_SUB((SELECT MAX(price_date) FROM portfolio_analysis.stock_prices), INTERVAL 12 MONTH)
  GROUP BY price_date
  HAVING MAX(CASE WHEN ticker='IXN' THEN ror END) IS NOT NULL
)
SELECT 'IXN' AS ticker, ROUND(STD(ixn_ror)*SQRT(252)*100, 2) AS sigma_12m_pct FROM daily
UNION ALL
SELECT 'QQQ',           ROUND(STD(qqq_ror)*SQRT(252)*100, 2) FROM daily
UNION ALL
SELECT 'IEF',           ROUND(STD(ief_ror)*SQRT(252)*100, 2) FROM daily
UNION ALL
SELECT 'VNQ',           ROUND(STD(vnq_ror)*SQRT(252)*100, 2) FROM daily
UNION ALL
SELECT 'GLD',           ROUND(STD(gld_ror)*SQRT(252)*100, 2) FROM daily
UNION ALL
SELECT 'PORTFOLIO',     ROUND(STD(port_ror)*SQRT(252)*100, 2) FROM daily;

-- ============================================================
-- QUESTION 4 (20 pts):
-- Based on Q1-Q3, which holdings would you sell, which would
-- you buy? Any outside securities to add?
--
-- This query combines 12M return, 12M sigma, and Sharpe ratio
-- for each ticker into one summary table to support the
-- buy/sell/hold decision.
--
-- Sharpe ratio = AVG(daily_ror) / STD(daily_ror) * SQRT(252)
-- Higher Sharpe = better risk-adjusted return.
-- ============================================================

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
),
daily AS (
  SELECT price_date,
         MAX(CASE WHEN ticker='IXN' THEN ror END) AS ixn_ror,
         MAX(CASE WHEN ticker='QQQ' THEN ror END) AS qqq_ror,
         MAX(CASE WHEN ticker='IEF' THEN ror END) AS ief_ror,
         MAX(CASE WHEN ticker='VNQ' THEN ror END) AS vnq_ror,
         MAX(CASE WHEN ticker='GLD' THEN ror END) AS gld_ror,
         0.175*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.221*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.285*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.089*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS port_ror
  FROM r
  WHERE ror IS NOT NULL
    AND price_date >= DATE_SUB((SELECT MAX(price_date) FROM portfolio_analysis.stock_prices), INTERVAL 12 MONTH)
  GROUP BY price_date
  HAVING MAX(CASE WHEN ticker='IXN' THEN ror END) IS NOT NULL
)
SELECT 'IXN' AS ticker,
       17.5  AS current_weight_pct,
       ROUND(AVG(ixn_ror)*252*100, 2)                        AS ann_return_12m_pct,
       ROUND(STD(ixn_ror)*SQRT(252)*100, 2)                  AS sigma_12m_pct,
       ROUND(AVG(ixn_ror)/STD(ixn_ror)*SQRT(252), 3)         AS sharpe_12m
FROM daily
UNION ALL
SELECT 'QQQ', 22.1,
       ROUND(AVG(qqq_ror)*252*100, 2),
       ROUND(STD(qqq_ror)*SQRT(252)*100, 2),
       ROUND(AVG(qqq_ror)/STD(qqq_ror)*SQRT(252), 3)
FROM daily
UNION ALL
SELECT 'IEF', 28.5,
       ROUND(AVG(ief_ror)*252*100, 2),
       ROUND(STD(ief_ror)*SQRT(252)*100, 2),
       ROUND(AVG(ief_ror)/STD(ief_ror)*SQRT(252), 3)
FROM daily
UNION ALL
SELECT 'VNQ', 8.9,
       ROUND(AVG(vnq_ror)*252*100, 2),
       ROUND(STD(vnq_ror)*SQRT(252)*100, 2),
       ROUND(AVG(vnq_ror)/STD(vnq_ror)*SQRT(252), 3)
FROM daily
UNION ALL
SELECT 'GLD', 23.0,
       ROUND(AVG(gld_ror)*252*100, 2),
       ROUND(STD(gld_ror)*SQRT(252)*100, 2),
       ROUND(AVG(gld_ror)/STD(gld_ror)*SQRT(252), 3)
FROM daily
UNION ALL
SELECT 'PORTFOLIO', 100.0,
       ROUND(AVG(port_ror)*252*100, 2),
       ROUND(STD(port_ror)*SQRT(252)*100, 2),
       ROUND(AVG(port_ror)/STD(port_ror)*SQRT(252), 3)
FROM daily;

-- Use the results above to determine:
-- BUY:  tickers with high Sharpe ratio and strong 12M return
-- HOLD: tickers with moderate performance or diversification value
-- SELL: tickers with negative Sharpe or poor risk-adjusted return
-- ADD:  consider adding an emerging markets ETF (e.g., IEMG)
--       for geographic diversification outside US tech/bonds

-- ============================================================
-- QUESTION 5 (20 pts):
-- How will portfolio risk and expected returns change after
-- rebalancing (selling and buying)?
--
-- Compares CURRENT mix vs. RECOMMENDED target mix.
-- Current:     IXN 17.5%  QQQ 22.1%  IEF 28.5%  VNQ 8.9%  GLD 23.0%
-- Recommended: IXN 20.0%  QQQ 25.0%  IEF 25.0%  VNQ 7.0%  GLD 23.0%
--
-- Part A: Side-by-side annual return, risk, Sharpe by year
-- Part B: Diversification benefit comparison
-- ============================================================

-- Part A: Current mix vs. Recommended mix by year

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
),
daily AS (
  SELECT price_date,
         YEAR(price_date) AS yr,
         -- Current portfolio mix
         0.175*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.221*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.285*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.089*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS curr_ror,
         -- Recommended target mix
         0.200*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.250*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.250*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.070*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS rec_ror
  FROM r
  WHERE ror IS NOT NULL
  GROUP BY price_date
  HAVING MAX(CASE WHEN ticker='IXN' THEN ror END) IS NOT NULL
)
SELECT yr,
       'CURRENT MIX' AS portfolio,
       ROUND(AVG(curr_ror)*252*100, 2)                        AS ann_return_pct,
       ROUND(STD(curr_ror)*SQRT(252)*100, 2)                  AS ann_risk_pct,
       ROUND(AVG(curr_ror)/STD(curr_ror)*SQRT(252), 3)        AS ann_sharpe
FROM daily GROUP BY yr
UNION ALL
SELECT yr,
       'RECOMMENDED TARGET MIX',
       ROUND(AVG(rec_ror)*252*100, 2),
       ROUND(STD(rec_ror)*SQRT(252)*100, 2),
       ROUND(AVG(rec_ror)/STD(rec_ror)*SQRT(252), 3)
FROM daily GROUP BY yr
ORDER BY yr, portfolio;

-- Part B: Diversification benefit comparison

WITH r AS (
  SELECT ticker, price_date,
         (adj_close - LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date))
         / LAG(adj_close) OVER (PARTITION BY ticker ORDER BY price_date) AS ror
  FROM portfolio_analysis.stock_prices
),
per_ticker AS (
  SELECT ticker, STD(ror)*SQRT(252)*100 AS ann_risk_pct
  FROM r
  WHERE ror IS NOT NULL
  GROUP BY ticker
),
daily AS (
  SELECT price_date,
         0.175*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.221*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.285*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.089*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS curr_ror,
         0.200*MAX(CASE WHEN ticker='IXN' THEN ror END)
       + 0.250*MAX(CASE WHEN ticker='QQQ' THEN ror END)
       + 0.250*MAX(CASE WHEN ticker='IEF' THEN ror END)
       + 0.070*MAX(CASE WHEN ticker='VNQ' THEN ror END)
       + 0.230*MAX(CASE WHEN ticker='GLD' THEN ror END) AS rec_ror
  FROM r
  WHERE ror IS NOT NULL
  GROUP BY price_date
  HAVING MAX(CASE WHEN ticker='IXN' THEN ror END) IS NOT NULL
)
SELECT
  ROUND((SELECT AVG(ann_risk_pct) FROM per_ticker), 2)         AS naive_avg_individual_risk_pct,
  ROUND((SELECT STD(curr_ror)*SQRT(252)*100 FROM daily), 2)    AS current_mix_risk_pct,
  ROUND((SELECT STD(rec_ror)*SQRT(252)*100 FROM daily), 2)     AS recommended_mix_risk_pct,
  ROUND((SELECT AVG(ann_risk_pct) FROM per_ticker)
        - (SELECT STD(curr_ror)*SQRT(252)*100 FROM daily), 2)  AS current_diversification_benefit_pts,
  ROUND((SELECT AVG(ann_risk_pct) FROM per_ticker)
        - (SELECT STD(rec_ror)*SQRT(252)*100 FROM daily), 2)   AS recommended_diversification_benefit_pts;

-- ============================================================
-- END OF SCRIPT
